class Solution { fun fallingSquares(positions:Array<IntArray>):List<Int>{val placed=mutableListOf<IntArray>();val answer=mutableListOf<Int>();var maximum=0;for(position in positions){val left=position[0];val right=left+position[1];var base=0;for(square in placed)if(maxOf(left,square[0])<minOf(right,square[1]))base=maxOf(base,square[2]);val height=base+position[1];placed.add(intArrayOf(left,right,height));maximum=maxOf(maximum,height);answer.add(maximum)};return answer} }
